// Earlybird logo lockup for the app chrome — mark plus wordmark, matching the
// web app's header brand treatment.
export function EarlybirdLockup(): React.JSX.Element {
  return (
    <span className="inline-flex items-center gap-2" aria-label="Opentake">
      <EarlybirdMark className="h-6 w-[21px]" />
      <span className="text-xl font-bold tracking-tight">Opentake</span>
    </span>
  );
}

