// Robinhood mark on its Robin Neon tile — matches the web app's RobinhoodLogoTile.
export function RobinhoodLogoTile({
  className,
  markClassName,
}: {
  className?: string;
  markClassName?: string;
}): React.JSX.Element {
  return (
    <span
      className={`inline-flex shrink-0 items-center justify-center rounded-full bg-[#ccff00] text-black ${className ?? ''}`}
      aria-hidden="true"
    >
      <RobinhoodMark className={markClassName} />
    </span>
  );
}

// Earlybird × Robinhood co-brand lockup.
export function BrandLockup(): React.JSX.Element {
  return (
    <div className="mb-6 flex items-center justify-center gap-3" aria-label="Opentake and Robinhood">
      <span className="inline-flex size-12 items-center justify-center rounded-full border border-border bg-card">
        <EarlybirdMark className="size-7" />
      </span>
      <span className="text-lg text-muted-foreground" aria-hidden="true">
        ×
      </span>
      <span className="inline-flex size-12 items-center justify-center rounded-full bg-[#ccff00] text-black">
        <RobinhoodMark className="size-6" />
      </span>
    </div>
  );
}

// Official Coinbase Design System mark (size-specific geometry).
// https://github.com/coinbase/cds/blob/master/packages/common/src/hooks/useLogo.ts
export function CoinbaseMark({ size = 32, ...props }: SVGProps<SVGSVGElement> & { size?: 16 | 24 | 32 }): React.JSX.Element {
  const marks = {
    16: { viewBox: '0 0 16 16', path: 'M8,12c-2.21,0-4-1.79-4-4c0-2.21,1.79-4,4-4c1.86,0,3.41,1.28,3.86,3h4.07C15.44,3.05,12.08,0,8,0 C3.58,0,0,3.58,0,8c0,4.42,3.58,8,8,8c4.08,0,7.44-3.05,7.93-7h-4.07C11.41,10.72,9.86,12,8,12z' },
    24: { viewBox: '0 0 24 24', path: 'M12.0225 18C8.70131 18 6.01127 15.315 6.01127 12C6.01127 8.685 8.70131 6 12.0225 6C14.9981 6 17.4678 8.165 17.9436 11H24C23.489 4.84 18.3244 0 12.0225 0C5.3851 0 0 5.375 0 12C0 18.625 5.3851 24 12.0225 24C18.3244 24 23.489 19.16 24 13H17.9436C17.4678 15.835 14.9981 18 12.0225 18Z' },
    32: { viewBox: '0 0 48 48', path: 'M24,36c-6.63,0-12-5.37-12-12s5.37-12,12-12c5.94,0,10.87,4.33,11.82,10h12.09C46.89,9.68,36.58,0,24,0 C10.75,0,0,10.75,0,24s10.75,24,24,24c12.58,0,22.89-9.68,23.91-22H35.82C34.87,31.67,29.94,36,24,36z' },
  };
  const mark = marks[size];
  return <svg viewBox={mark.viewBox} width={size} height={size} aria-hidden="true" focusable="false" {...props}>
    <path d={mark.path} className="coinbase-mark-path" />
  </svg>;
}
